cat > reports/TourismTaxReport.java <<'EOF'
package hotel.reports;

import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** The tourism tax owed to the city on the paid reservations that start in a given month (CSV). */
public final class TourismTaxReport {

    private final ReservationStore store;
    private final BigDecimal taxPerGuestNight;

    public TourismTaxReport(ReservationStore store, BigDecimal taxPerGuestNight) {
        this.store = store;
        this.taxPerGuestNight = taxPerGuestNight;
    }

    public String generate(YearMonth month) {
        List<Reservation> taxed = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            if (reservation.isPaid() && YearMonth.from(reservation.checkIn()).equals(month)) {
                taxed.add(reservation);
            }
        }
        taxed.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));

        List<String> rows = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Reservation reservation : taxed) {
            int nights = reservation.price().nights();
            BigDecimal tax = taxPerGuestNight.multiply(BigDecimal.valueOf((long) reservation.guests() * nights))
                    .setScale(2, java.math.RoundingMode.HALF_EVEN);
            rows.add(reservation.id() + "," + reservation.roomNumber() + "," + reservation.checkIn() + ","
                    + reservation.checkOut() + "," + reservation.guests() + "," + nights + ","
                    + tax.toPlainString());
            total = total.add(tax);
        }
        return ReportLayout.render("tourism-tax", month, "reservation,room,check_in,check_out,guests,nights,tax",
                rows, "total," + total.toPlainString());
    }
}
EOF
cat > reports/RatePlanReport.java <<'EOF'
package hotel.reports;

import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** The reservations and the money kept per rate plan, over the reservations the revenue report counts (CSV). */
public final class RatePlanReport {

    private final RevenueReport revenue;

    public RatePlanReport(RevenueReport revenue) {
        this.revenue = revenue;
    }

    public String generate(YearMonth month) {
        List<Reservation> counted = revenue.reservationsWithRevenue(month);
        List<String> rows = new ArrayList<>();
        int totalReservations = 0;
        BigDecimal totalAmount = BigDecimal.ZERO.setScale(2);
        for (RatePlan plan : RatePlan.values()) {
            int count = 0;
            BigDecimal amount = BigDecimal.ZERO.setScale(2);
            for (Reservation reservation : counted) {
                if (reservation.ratePlan() == plan) {
                    count++;
                    amount = amount.add(reservation.amountKept());
                }
            }
            rows.add(plan + "," + count + "," + amount.toPlainString());
            totalReservations += count;
            totalAmount = totalAmount.add(amount);
        }
        return ReportLayout.render("rate-plans", month, "rate_plan,reservations,amount", rows,
                "total," + totalReservations + "," + totalAmount.toPlainString());
    }
}
EOF
